import {ZONES} from './content.js';
export function earthArt(kind='map',success=false){
 const base=`<defs><linearGradient id="ce-sky" x2="0" y2="1"><stop stop-color="#223955"/><stop offset="1" stop-color="#798a9d"/></linearGradient><linearGradient id="ce-rock" x2="1" y2="1"><stop stop-color="#829cbe"/><stop offset="1" stop-color="#4b5f83"/></linearGradient></defs><rect width="640" height="320" rx="24" fill="url(#ce-sky)"/><g fill="#fff0bd">${[30,125,210,420,590].map((x,i)=>`<circle cx="${x}" cy="${20+i%3*22}" r="2"/>`).join('')}</g>`;
 const volcano=`<path d="M80 270L235 74h72l170 196" fill="#79616e"/><path d="M235 74h72l26 31-56-13-42 12-29 0z" fill="#ffd2a0"/><path d="M259 92q-40 67 0 102t-40 76h82q32-61-11-103t-9-75" fill="#ff9b61"/><ellipse cx="276" cy="270" rx="120" ry="32" fill="#ff854f"/>`;
 let drawing='';
 if(['map','magma','lava','igneous'].includes(kind))drawing=volcano+`<path d="M0 270h640v50H0z" fill="#4e405d"/>${kind==='magma'?'<path d="M195 276q120-45 180 0v35H195z" fill="#ffbc70"/><path d="M470 265h100m-50 0v35" stroke="#fff1c8" stroke-width="4"/><text x="475" y="247" fill="#fff1c8" font-size="21">SURFACE</text><text x="203" y="303" fill="#613c4f" font-size="22" font-weight="bold">BELOW</text>':kind==='lava'?'<path d="M282 126q90 90 267 117" stroke="#ffba76" stroke-width="25" fill="none"/><text x="375" y="211" fill="#fff7d4" font-size="24">ON THE SURFACE</text>':''}${kind==='igneous'&&success?'<path d="M350 260l20-74 97-21 71 75-40 40H370z" fill="url(#ce-rock)"/><g fill="#bcead9"><circle cx="393" cy="215" r="5"/><circle cx="450" cy="245" r="5"/><circle cx="489" cy="219" r="5"/></g>':''}`;
 else if(kind==='sedimentary')drawing=`<path d="M145 270V110l185-24 175 32v152z" fill="#c58f71"/><path d="M145 150l185-24 175 32M145 194l185-14 175 18M145 235l185-20 175 26" stroke="#ffe3a4" stroke-width="20"/>${success?'<path d="M130 100h390M130 280h390" stroke="#90e5d6" stroke-width="9"/>':'<g fill="#ffe3a4"><circle cx="110" cy="62" r="12"/><circle cx="380" cy="40" r="9"/><circle cx="530" cy="84" r="14"/></g>'}`;
 else if(kind==='metamorphic')drawing=`<path d="M180 260V114l160-38 139 65v126z" fill="#8e8eaf"/><path d="M184 166q60-56 129-4t160 10M181 226q68-60 142-4t150 0" stroke="#d7b8e0" stroke-width="16" fill="none"/><g fill="#ffbb73"><path d="M66 174h63v-30l48 48-48 48v-30H66zM574 174h-63v-30l-48 48 48 48v-30h63z"/></g>${success?'<g fill="#b5f2df"><path d="M315 35l7 15 17 3-13 12 3 17-14-8-15 8 3-17-12-12 17-3z"/></g>':''}`;
 else if(kind==='mineral')drawing=`<g stroke="#d4fff1" stroke-width="3" fill="#8ee8de"><path d="M210 270V130l45-72 45 72v140z"/><path d="M300 270V105l55-80 55 80v165z"/><path d="M410 270V170l35-55 40 55v100z"/></g><path d="M210 130h90m0-25h110m-55-80v245m-100-212v212" stroke="#d4fff1" stroke-width="3"/>`;
 else if(['sand','dune','plants'].includes(kind))drawing=`<path d="M0 250q140-100 300 0t340-18v88H0z" fill="#dab680"/><path d="M0 282q200-90 340-25t300 13v50H0" fill="#efce92"/><g fill="none" stroke="#ffe4aa" stroke-width="4"><path d="M60 130q170-50 300 0t190-30M20 160q140-40 300 0t240-25"/></g>${kind==='plants'?`<g stroke="#9fe1a5" stroke-width="12" fill="none"><path d="M345 250V110m0 70q-90 0-85-65 70 0 85 65m0 25q85-5 75-62-58 0-75 62"/></g>${success?'<path d="M345 247v30m0-10-78 40m78-30 76 27m-76-44-30 50m30-30 40 34" stroke="#976744" stroke-width="7"/>':''}`:success?'<path d="M250 300q100-170 300-10z" fill="#f8d99d"/><path d="M390 206l-37 88" stroke="#e6b676" stroke-width="4"/>':''}`;
 else if(kind==='crust')drawing=`<circle cx="320" cy="174" r="118" fill="#ffd38e" stroke="#8bba8b" stroke-width="24"/><path d="M310 50q-100 50-65 98t-25 91m173-150q-70 50-26 74t4 101" stroke="#6ca5c5" stroke-width="25" fill="none"/><path d="M441 137l90-40" stroke="#fff2bb" stroke-width="4"/><text x="480" y="82" fill="#fff2bb" font-size="27">CRUST</text>`;
 else drawing=`<path d="M0 310L160 185l130 50L480 85l160 225z" fill="#9c7a73"/><path d="M155 266l60-95 160-28 95 89-48 46z" fill="url(#ce-rock)"/>${kind==='wind'?'<g stroke="#d3f7eb" stroke-width="5" fill="none"><path d="M40 80h160q50-10 20-35M20 113h220M60 145h135q55 0 27 30"/></g>':kind==='water'?'<g fill="#8edce9"><path d="M210 24q-70 100 0 100t0-100M350 38q-60 80 0 80t0-80"/></g>':kind==='ice'?'<g fill="#acdfed" stroke="#e8fcfa" stroke-width="4"><path d="M230 70l48-30 52 30-12 68h-74z"/><path d="M278 40v80m-48-50 48 25 52-25"/></g>':kind==='living'?'<path d="M330 245V66m0 93q-80-2-90-70 74 0 90 70m0-31q65-55 100-40-14 60-100 80" stroke="#a0d599" stroke-width="12" fill="none"/>':kind==='temperature'?'<circle cx="180" cy="80" r="35" fill="#ffcb84"/><path d="M460 40v80m-40-40h80m-70-30 60 60m0-60-60 60" stroke="#b2e8ef" stroke-width="6"/>':kind==='landslide'?'<g fill="#cea487"><path d="M435 120l-20 48 52 10 15-30zM380 180l-35 40 40 38 40-28zM300 240l-30 48 58 8 22-45z"/></g><path d="M490 154l-150 130m0 0 4-45m-4 45 48-7" stroke="#ffe3a5" stroke-width="9" fill="none"/>':''}${success?'<path d="M300 166l-29 45 41 17-42 48m50-110 19 34-11 28 48 38" stroke="#ffdc9b" stroke-width="7" fill="none"/>':''}`;
 const particles=['sand','dune','wind'].includes(kind)?`<g fill="#ffe7b3">${Array.from({length:18},(_,i)=>`<circle class="earth-sand-grain" style="animation-delay:${-i*.17}s" cx="${40+i*29}" cy="${140+i%5*14}" r="${2+i%3}"/>`).join('')}</g>`:'';
 return `<svg class="earth-illustration earth-visual-${kind} ${success?'earth-success':''}" viewBox="0 0 640 320" role="img" aria-label="${({magma:'Molten rock below the surface',lava:'Molten rock on the surface',igneous:'Cooling rock machine',sedimentary:'Layers of sediments',metamorphic:'Heat and pressure changing rock',mineral:'A solid cluster of crystals',plants:'Plants and roots holding soil',sand:'Wind moving sand',dune:'Sand building dunes',crust:'The changing crust',wind:'Wind blowing across rock',water:'Water wearing rock',ice:'Ice acting on rock',living:'Plant roots in rock',temperature:'Warm and cold changes',landslide:'Rock sliding rapidly downhill'})[kind]||'Changing Earth expedition'}">${base}${drawing}${particles}<g fill="#e8fff0">${success?[60,140,510,580].map((x,i)=>`<path d="M${x} ${60+i%2*120}l4 12 12 4-12 4-4 12-4-12-12-4 12-4z"/>`).join(''):''}</g></svg>`;
}

export function drawJourney(c,world,player,zone,camera,collected,time){
 const z=ZONES[zone];c.clearRect(0,0,960,340);const sky=c.createLinearGradient(0,0,0,340);sky.addColorStop(0,z.sky);sky.addColorStop(1,z.ground);c.fillStyle=sky;c.fillRect(0,0,960,340);
 for(let i=0;i<14;i++){const x=((i*199-camera*.2)%1100+1100)%1100-70;c.fillStyle=z.glow+'66';c.beginPath();c.arc(x,30+(i%4)*23,2+i%3,0,Math.PI*2);c.fill();}
 c.save();c.translate(-camera*.15,0);c.fillStyle='#0d2a3c44';for(let x=-100;x<3900;x+=400){c.beginPath();c.moveTo(x,270);c.lineTo(x+180,60+(zone%3)*25);c.lineTo(x+400,270);c.fill();}c.restore();
 if(zone===0){c.fillStyle='#9b6674';c.beginPath();c.moveTo(530,270);c.lineTo(680,90);c.lineTo(735,90);c.lineTo(930,270);c.fill();c.strokeStyle='#ffaf71';c.lineWidth=18;c.beginPath();c.moveTo(705,94);c.lineTo(680+Math.sin(time)*7,150);c.lineTo(760,245);c.stroke();}
 c.save();c.translate(-camera,0);
 for(const p of world.platforms){c.fillStyle=z.ground;c.fillRect(p.x,p.y,p.w,p.h);c.fillStyle=z.glow;c.fillRect(p.x,p.y,p.w,7);if(p.ground){c.fillStyle='#ffffff15';for(let x=p.x;x<p.x+p.w;x+=80)c.fillRect(x,p.y+28,45,5);}}
 for(let i=0;i<8;i++){if(collected.includes(zone+'-'+i))continue;const g=world.crystals[i],y=g.y+Math.sin(time*3+i)*5;c.fillStyle='#91f0df';c.shadowColor='#9bffe9';c.shadowBlur=14;c.beginPath();c.moveTo(g.x,y-15);c.lineTo(g.x+10,y);c.lineTo(g.x,y+15);c.lineTo(g.x-10,y);c.closePath();c.fill();c.shadowBlur=0;}
 for(const x of [1100,1900]){c.fillStyle='#a8a0a5';c.beginPath();c.ellipse(x,260,30,17,0,0,Math.PI*2);c.fill();}
 c.fillStyle=z.glow;c.fillRect(2880,92,15,178);c.fillRect(3065,92,15,178);c.fillRect(2880,85,200,18);c.fillStyle=z.glow+'33';c.fillRect(2895,103,170,167);c.font='bold 20px Trebuchet MS';c.textAlign='center';c.fillStyle='#fff3cb';c.fillText('CRYSTAL GATE',2980,65);
 const p=player;c.save();c.translate(p.x+p.w/2,p.y+p.h);c.scale(p.face,1);const bob=p.grounded&&p.vx?Math.sin(time*14)*3:0;c.translate(0,bob);c.strokeStyle='#314a72';c.lineWidth=9;c.lineCap='round';const run=p.grounded&&p.vx?Math.sin(time*14)*8:0;c.beginPath();c.moveTo(-8,-19);c.lineTo(-10-run,-2);c.moveTo(8,-19);c.lineTo(10+run,-2);c.stroke();c.fillStyle=p.hurt?'#ffce9a':'#8de0d0';c.fillRect(-14,-45,28,29);c.strokeStyle='#ffd9b7';c.lineWidth=7;c.beginPath();c.moveTo(-15,-40);c.lineTo(-22,-24-run);c.moveTo(15,-40);c.lineTo(22,-24+run);c.stroke();c.fillStyle='#ffdab7';c.beginPath();c.arc(0,-60,17,0,Math.PI*2);c.fill();c.fillStyle='#ffda8b';c.fillRect(-23,-71,46,8);c.beginPath();c.arc(-2,-73,17,Math.PI,0);c.fill();c.fillStyle='#2e425e';c.beginPath();c.arc(7,-60,2,0,Math.PI*2);c.fill();c.strokeStyle='#b87666';c.lineWidth=2;c.beginPath();c.arc(5,-55,5,0,Math.PI*.7);c.stroke();c.restore();c.restore();
 c.fillStyle='#ffffffc0';c.font='bold 18px Trebuchet MS';c.textAlign='left';c.fillText(z.tag,28,35);
}
